describe('Request Timeout Error Handling', () => {
  beforeEach(() => {
    cy.visit('/api/data');
  });

  it('should display timeout error when request takes longer than 10 seconds', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      delay: 12000,
      body: { data: 'Success' }
    }).as('dataRequest');

    cy.get('[data-testid="request-button"]').click();
    cy.wait('@dataRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(504);
      expect(interception.response.statusCode).to.equal(504);
      cy.get('[data-testid="error-message"]').should('be.visible');
      cy.get('[data-testid="error-message"]').should('contain', 'Request timed out');
      cy.get('[data-testid="error-message"]').should('contain', 'Please try again');
    });
  });

  it('should not display timeout error when request completes within 10 seconds', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      delay: 5000,
      body: { data: 'Success' }
    }).as('fastDataRequest');

    cy.get('[data-testid="request-button"]').click();
    cy.wait('@fastDataRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.statusCode).to.equal(200);
      cy.get('[data-testid="error-message"]').should('not.exist');
      cy.get('[data-testid="data-table"]').should('be.visible');
      cy.get('[data-testid="data-row"]').should('contain', 'Success');
    });
  });
});
